package com.stocksense.service;

import com.stocksense.domain.WatchlistItem;
import com.stocksense.exception.StockSenseException;
import com.stocksense.market.MarketModels.QuoteData;
import com.stocksense.repository.WatchlistRepository;
import com.stocksense.util.Symbols;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.regex.Pattern;

/** Per-owner watchlists. The owner is an opaque client id generated by the dashboard (no accounts yet). */
@Service
public class WatchlistService {

    public static final int MAX_ITEMS = 25;
    private static final Pattern OWNER = Pattern.compile("^[A-Za-z0-9_-]{8,64}$");

    public record Entry(String symbol, String name, Double price, Double change, Double changePercent,
                        String currency, String source, Instant addedAt) {
    }

    private final WatchlistRepository repository;
    private final MarketDataService market;

    public WatchlistService(WatchlistRepository repository, MarketDataService market) {
        this.repository = repository;
        this.market = market;
    }

    public List<Entry> list(String rawOwner) {
        String owner = owner(rawOwner);
        List<Entry> out = new ArrayList<>();
        for (WatchlistItem item : repository.findByOwnerOrderByAddedAtAsc(owner)) {
            try {
                QuoteData q = market.quote(item.getSymbol());
                out.add(new Entry(item.getSymbol(), q.name(), q.price(), q.change(), q.changePercent(), q.currency(),
                        q.source(), item.getAddedAt()));
            } catch (RuntimeException e) {
                out.add(new Entry(item.getSymbol(), item.getSymbol(), null, null, null, null, null, item.getAddedAt()));
            }
        }
        return out;
    }

    /** Returns true when the symbol was added, false when it was already on the list. */
    public boolean add(String rawOwner, String rawSymbol) {
        String owner = owner(rawOwner);
        String symbol = Symbols.normalize(rawSymbol);
        if (repository.findByOwnerAndSymbol(owner, symbol).isPresent()) {
            return false;
        }
        if (repository.countByOwner(owner) >= MAX_ITEMS) {
            throw new StockSenseException.InvalidRequest("Watchlist is full (max " + MAX_ITEMS + " symbols)");
        }
        market.quote(symbol); // validates that the symbol exists
        repository.save(new WatchlistItem(owner, symbol));
        return true;
    }

    @Transactional
    public boolean remove(String rawOwner, String rawSymbol) {
        Optional<WatchlistItem> item = repository.findByOwnerAndSymbol(owner(rawOwner), Symbols.normalize(rawSymbol));
        item.ifPresent(repository::delete);
        return item.isPresent();
    }

    public long count(String rawOwner) {
        return repository.countByOwner(owner(rawOwner));
    }

    private static String owner(String raw) {
        if (raw == null || !OWNER.matcher(raw.trim()).matches()) {
            throw new StockSenseException.InvalidRequest("owner must be 8-64 characters of letters, digits, '-' or '_'");
        }
        return raw.trim();
    }
}
